/** Separate active-window budget. Never replaces the broad Controller timing
 * result. All profiles/gear are private; boss AI/health and player vulnerability
 * remain native. No measured tick is manufactured or used for earned rewards. */
public final class LoadNativeChecks {
 private static MinecraftServer server;private static List<ArenaDirector.Definition> definitions;private static ArenaDirector.Definition d;
 private static JsonObject report,row,run;private static JsonArray cases,failures,damage;private static String nonce,ownedRun;
 private static final List<EntityPlayerMP> party=new ArrayList<>();private static final Map<UUID,Integer> useStart=new HashMap<>(),useCompleted=new HashMap<>(),playerStart=new HashMap<>();
 private static final List<Long> allTimes=new ArrayList<>();private static final Map<Integer,List<Long>> bySize=new TreeMap<>();
 private static final Recorder recorder=new Recorder();private static EntityLivingBase boss;private static int arenaIndex,partySize,stage,age,total,clickPhase,cleanupAge,bodyStart,measurementBodyLast;
 private static boolean done,measuring,measurementRecorded;private static long started,caseStarted,caseWorldStart,worldStart,firstSample,lastSample;private static final List<Long> times=new ArrayList<>();
 private static int targetTicks,bodyUpdates,maxChunks,maxEntities,maxEffects,maxAllies,maxJournal,dodgeAccepted,dodgeAttempts;private static long peakHeap;
 private static int nativeAttacks,hazardAttacks,unattributedAttacks;private static final List<Damage> pending=new ArrayList<>();
 private static final class Damage {final LivingAttackEvent e;final JsonObject destination;Damage(LivingAttackEvent e,JsonObject d){this.e=e;destination=d;}}
 private LoadNativeChecks(){}
 private static WorldServer world(){return server.getWorld(0);}
 private static void require(boolean okay,String text){if(!okay)throw new IllegalStateException(text);}
 public static void begin(MinecraftServer s,List<ArenaDirector.Definition> defs){
  require(Boolean.getBoolean("hbv.arenas.nativeProbe")&&Files.isRegularFile(Paths.get(".hbv-arenas-native-probe"))&&s.getFolderName().equals("arena-preview")&&s.getPlayerList().getCurrentPlayerCount()==0,"Standalone load requires fresh guarded profile-free fixture");
  require(defs.size()==5,"Exactly five installed arena definitions required");server=s;definitions=new ArrayList<>(defs);nonce=UUID.randomUUID().toString();arenaIndex=stage=age=total=cleanupAge=0;partySize=1;done=measuring=false;started=System.nanoTime();party.clear();allTimes.clear();bySize.clear();pending.clear();
  report=new JsonObject();cases=new JsonArray();report.add("cases",cases);report.addProperty("scope","SEPARATE_STANDALONE_ACTIVE_ENCOUNTER_100_TICKS_PER_ARENA_PARTY_SIZE; synthetic guided official players, no physical client");report.addProperty("broad_controller_p99_failure_replaced_or_promoted",false);report.addProperty("preview_is_administrative_test_only",true);report.addProperty("boss_health_phase_credit_assignment_or_ai_disabling",false);report.addProperty("player_health_setter_or_invulnerability",false);report.addProperty("os",System.getProperty("os.name"));report.addProperty("arch",System.getProperty("os.arch"));report.addProperty("cpu",System.getenv("PROCESSOR_IDENTIFIER"));report.addProperty("available_processors",Runtime.getRuntime().availableProcessors());report.addProperty("max_heap_bytes",Runtime.getRuntime().maxMemory());MinecraftForge.EVENT_BUS.register(recorder);
 }
 public static JsonObject result(){return report;}
 public static EntityPlayerMP currentPlayer(){return null;}
 private static void warm(int[] at){NativeProbe.prewarm(world(),new BlockPos(at[0],at[1],at[2]));}
 private static void guide(EntityPlayerMP p,int[] at){warm(at);require(ArenaDirector.safe(world(),at),"Guided load landing lacks support/clearance");p.connection.setPlayerLocation(at[0]+.5,at[1],at[2]+.5,p.rotationYaw,p.rotationPitch);p.fallDistance=0;world().getPlayerChunkMap().updateMovingPlayer(p);}
 private static void near(EntityPlayerMP p,int[] node){for(int[] offset:new int[][]{{0,-3},{0,3},{-3,0},{3,0}}){int[] at={node[0]+offset[0],d.floor,node[2]+offset[1]};warm(at);if(ArenaDirector.safe(world(),at)){guide(p,at);return;}}throw new IllegalStateException("Physical seal has no supported approach");}
 private static void click(EntityPlayerMP p,int node){int[] at=d.nodes[node];near(p,at);ForgeHooks.onRightClickBlock(p,EnumHand.MAIN_HAND,new BlockPos(at[0],at[1],at[2]),EnumFacing.UP,new Vec3d(at[0]+.5,at[1]+.5,at[2]+.5));}
 private static void equip(EntityPlayerMP p){
  p.inventory.clear();net.minecraft.item.Item[] armor={Items.DIAMOND_HELMET,Items.DIAMOND_CHESTPLATE,Items.DIAMOND_LEGGINGS,Items.DIAMOND_BOOTS};EntityEquipmentSlot[] slots={EntityEquipmentSlot.HEAD,EntityEquipmentSlot.CHEST,EntityEquipmentSlot.LEGS,EntityEquipmentSlot.FEET};
  for(int i=0;i<4;i++){ItemStack stack=new ItemStack(armor[i]);stack.addEnchantment(Enchantments.PROTECTION,4);p.setItemStackToSlot(slots[i],stack);}p.setItemStackToSlot(EntityEquipmentSlot.OFFHAND,new ItemStack(Items.SHIELD));p.inventory.currentItem=0;p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(Items.GOLDEN_APPLE,1,1));
 }
 private static void startCase(){
  d=definitions.get(arenaIndex);row=new JsonObject();failures=new JsonArray();damage=new JsonArray();row.addProperty("arena",d.id);row.addProperty("party_size",partySize);row.addProperty("target_seal_phase",Math.min(partySize,3));row.addProperty("template_sha256",d.template_sha256);row.add("failures",failures);row.add("actual_damage_events",damage);caseStarted=System.nanoTime();caseWorldStart=world().getTotalWorldTime();age=0;ownedRun="";run=null;boss=null;party.clear();useStart.clear();useCompleted.clear();playerStart.clear();times.clear();measurementRecorded=false;JsonObject previous=ArenaDirector.run(d);require(previous==null||ArenaDirector.text(previous,"state").equals("AVAILABLE"),"Preexisting nonempty arena preserved");warm(d.entry);warm(d.exit);warm(d.boss_anchor);
  for(int i=0;i<partySize;i++){
   UUID id=UUID.nameUUIDFromBytes(("HBV:LOAD:"+nonce+":"+arenaIndex+":"+partySize+":"+i).getBytes(StandardCharsets.UTF_8));require(server.getPlayerList().getPlayerByUUID(id)==null&&!Files.exists(Paths.get("arena-preview","playerdata",id+".dat")),"Private load UUID already exists");EntityPlayerMP p=new EntityPlayerMP(server,world(),new GameProfile(id,"HbvLoad"+arenaIndex+partySize+i),new PlayerInteractionManager(world()));p.connection=new NativeProbe.Quiet(server,p);server.getPlayerList().initializeConnectionToPlayer(p.connection.netManager,p,p.connection);require(server.getPlayerList().getPlayerByUUID(id)==p&&world().playerEntities.contains(p),"Official load profile login failed");p.setGameType(GameType.SURVIVAL);party.add(p);equip(p);ArenaIntro.start(p,d);click(p,0);
  }stage=1;age=0;
 }
 private static boolean alive(){for(EntityPlayerMP p:party)if(server.getPlayerList().getPlayerByUUID(p.getUniqueID())!=p||!p.isEntityAlive()||p.isCreative()||p.isSpectator()||p.capabilities.disableDamage||p.isEntityInvulnerable(DamageSource.GENERIC))return false;return true;}
 private static void engage(){
  int[][] offsets={{12,0},{-12,0},{0,12},{0,-12},{16,0},{-16,0},{0,16},{0,-16}};Set<String> used=new HashSet<>();
  for(int i=0;i<party.size();i++){boolean placed=false;for(int k=0;k<offsets.length;k++){int[] off=offsets[(i+k)%offsets.length];int[] at={(int)Math.floor(boss.posX)+off[0],d.floor,(int)Math.floor(boss.posZ)+off[1]};warm(at);if(d.contains(new BlockPos(at[0],at[1],at[2]))&&ArenaDirector.safe(world(),at)&&used.add(Arrays.toString(at))){guide(party.get(i),at);placed=true;break;}}require(placed,"No supported native party engagement position");}
 }
 private static void defend(){
  if(boss==null||!boss.isEntityAlive()||run==null||!ArenaDirector.text(run,"state").startsWith("PHASE"))return;
  for(EntityPlayerMP p:party){if(!p.isEntityAlive())continue;double dx=boss.posX-p.posX,dz=boss.posZ-p.posZ,dist=Math.sqrt(dx*dx+dz*dz);if(dist<.01)continue;p.rotationYaw=(float)Math.toDegrees(Math.atan2(-dx,dz));p.rotationPitch=0;if(!p.isHandActive())p.setActiveHand(EnumHand.OFF_HAND);
   if(ArenaDirector.ticks%24==0){double before=MoveCost.view(p).amount;dodgeAttempts++;boolean accepted=village.vale.ArenaDodgeNativeAccess.perform(p,village.vale.DodgeMath.LEFT);if(accepted){double debit=before-MoveCost.view(p).amount;require(debit>0,"Canonical dodge accepted without actual native resource debit");dodgeAccepted++;}}
   double mx=-dz/dist*.07+p.motionX,mz=dx/dist*.07+p.motionZ,my=Math.max(-.6,p.motionY-.08);int[] at={(int)Math.floor(p.posX+mx),d.floor,(int)Math.floor(p.posZ+mz)};if(d.contains(new BlockPos(at[0],at[1],at[2]))&&ArenaDirector.safe(world(),at)){p.move(MoverType.SELF,mx,my,mz);p.motionX*=.6;p.motionZ*=.6;if(p.onGround)p.motionY=0;world().getPlayerChunkMap().updateMovingPlayer(p);}
  }
 }
 private static void beginMeasurement(){
  require(alive()&&boss.isEntityAlive()&&!(boss instanceof EntityLiving&&((EntityLiving)boss).isAIDisabled()),"Vulnerable party or active authentic boss unavailable");require(ArenaDirector.sealPhase(run)==Math.min(partySize,3)&&ArenaDirector.pressure(run,ArenaDirector.sealPhase(run))>=40,"Real phase pressure prerequisite not reached");
  for(EntityPlayerMP p:party){for(EntityEquipmentSlot slot:new EntityEquipmentSlot[]{EntityEquipmentSlot.HEAD,EntityEquipmentSlot.CHEST,EntityEquipmentSlot.LEGS,EntityEquipmentSlot.FEET})require(net.minecraft.enchantment.EnchantmentHelper.getEnchantmentLevel(Enchantments.PROTECTION,p.getItemStackFromSlot(slot))==4,"Real ProtectionIV loan armor missing at measurement");require(p.getHeldItemOffhand().getItem()==Items.SHIELD,"Real vanilla shield missing");require("narutomod".equals(MoveCost.view(p).provider)&&MoveCost.view(p).ready(),"Paid dodge needs actual native Ninja account");}
  JsonArray members=new JsonArray();for(EntityPlayerMP p:party){double before=MoveCost.view(p).amount;double restored=MoveCost.restore(p,200);JsonObject m=new JsonObject();m.addProperty("uuid",p.getUniqueID().toString());m.addProperty("health",p.getHealth());m.addProperty("absorption",p.getAbsorptionAmount());m.addProperty("chakra_before_bounded_preview_setup",before);m.addProperty("bounded_preview_restore_actual",restored);m.addProperty("chakra_at_measurement",MoveCost.view(p).amount);m.addProperty("actual_consumption_player_ticks",useCompleted.get(p.getUniqueID()));m.addProperty("regen_potion_native",p.isPotionActive(MobEffects.REGENERATION));m.addProperty("resistance_potion_native",p.isPotionActive(MobEffects.RESISTANCE));m.addProperty("absorption_potion_native",p.isPotionActive(MobEffects.ABSORPTION));members.add(m);require(p.isPotionActive(MobEffects.RESISTANCE)&&p.isPotionActive(MobEffects.ABSORPTION),"Native enchanted apple effects absent before measurement");playerStart.put(p.getUniqueID(),p.ticksExisted);}
  row.add("native_members_before",members);row.addProperty("real_seal_phase",ArenaDirector.sealPhase(run));row.addProperty("environment_phase",ArenaDirector.number(run,"phase"));row.addProperty("pressure_prerequisite",ArenaDirector.pressure(run,ArenaDirector.sealPhase(run)));row.addProperty("native_boss_class",boss.getClass().getName());row.addProperty("native_boss_class_sha256",ArenaTerminals.classHash(boss));row.addProperty("native_boss_health_before",boss.getHealth());row.addProperty("preparation_world_ticks",world().getTotalWorldTime()-caseWorldStart);row.addProperty("preparation_elapsed_ms",(System.nanoTime()-caseStarted)/1000000L);times.clear();targetTicks=bodyUpdates=maxChunks=maxEntities=maxEffects=maxAllies=maxJournal=dodgeAccepted=dodgeAttempts=nativeAttacks=hazardAttacks=unattributedAttacks=0;peakHeap=0;firstSample=lastSample=0;bodyStart=measurementBodyLast=boss.ticksExisted;worldStart=world().getTotalWorldTime();measuring=true;stage=50;
 }
 private static double percentile(List<Long> data,double fraction){if(data.isEmpty())return 0;List<Long> sorted=new ArrayList<>(data);Collections.sort(sorted);return sorted.get(Math.min(sorted.size()-1,(int)Math.ceil(sorted.size()*fraction)-1))/1e6;}
 private static JsonObject timing(List<Long> data){JsonObject r=new JsonObject();r.addProperty("samples",data.size());r.addProperty("p50_tick_ms",percentile(data,.50));r.addProperty("p95_tick_ms",percentile(data,.95));r.addProperty("p99_tick_ms",percentile(data,.99));r.addProperty("tick_targets_met",data.size()>0&&percentile(data,.95)<=50&&percentile(data,.99)<=100);return r;}
 private static void endMeasurement(){
  if(measurementRecorded)return;measurementRecorded=true;
  measuring=false;row.add("active_server_tick_budget",timing(times));row.add("actual_tick_durations_ns",ArenaDirector.JSON.toJsonTree(times));row.addProperty("actual_active_world_ticks",world().getTotalWorldTime()-worldStart);row.addProperty("actual_native_boss_ticks",boss.ticksExisted-bodyStart);row.addProperty("actual_native_boss_updating_samples",bodyUpdates);row.addProperty("native_targeting_party_samples",targetTicks);row.addProperty("native_attack_events",nativeAttacks);row.addProperty("owned_environment_attack_events",hazardAttacks);row.addProperty("actual_canonical_paid_dodges",dodgeAccepted);row.addProperty("canonical_dodge_attempts",dodgeAttempts);row.addProperty("max_loaded_chunks",maxChunks);row.addProperty("max_loaded_entities",maxEntities);row.addProperty("max_party_native_effects",maxEffects);row.addProperty("max_exact_owned_native_allies",maxAllies);row.addProperty("max_owned_journal_cells",maxJournal);row.addProperty("peak_used_heap_bytes",peakHeap);row.addProperty("native_boss_health_after",boss.getHealth());JsonArray players=new JsonArray();for(EntityPlayerMP p:party){JsonObject m=new JsonObject();m.addProperty("uuid",p.getUniqueID().toString());m.addProperty("actual_player_ticks",p.ticksExisted-playerStart.getOrDefault(p.getUniqueID(),p.ticksExisted));m.addProperty("alive",p.isEntityAlive());m.addProperty("health",p.getHealth());m.addProperty("absorption",p.getAbsorptionAmount());players.add(m);}row.add("native_members_after",players);allTimes.addAll(times);bySize.computeIfAbsent(partySize,k->new ArrayList<>()).addAll(times);
  row.addProperty("unattributed_attack_events",unattributedAttacks);row.addProperty("measured_start_end_span_seconds",lastSample>firstSample?(lastSample-firstSample)/1e9:0);for(EntityPlayerMP p:party)if(p.ticksExisted-playerStart.getOrDefault(p.getUniqueID(),p.ticksExisted)<100)failures.add("A real registered participant lacked100native player updates");if(dodgeAccepted<1)failures.add("No actual canonical paid dodge accepted during measured window");if(d.boss.equals("kabutoaddon:ay")&&maxAllies==0)failures.add("Native Ay ally load was not actually observed");if(times.size()!=100||!alive()||!boss.isEntityAlive()||bodyUpdates<100||targetTicks+nativeAttacks==0)failures.add("Active measurement lacked100 genuine updating vulnerable-party native combat samples");if(!timing(times).get("tick_targets_met").getAsBoolean())failures.add("Standalone active-window p95/p99 target failed");stage=80;cleanupAge=0;
 }
 private static void cleanup(){
  require(++cleanupAge<=180,"Exact owned public-exit/autoreset exceeded180ticks");measuring=false;
  for(int i=0;i<party.size();i++){EntityPlayerMP p=party.get(i);if(server.getPlayerList().getPlayerByUUID(p.getUniqueID())!=p)continue;if(!p.isEntityAlive()){p=server.getPlayerList().recreatePlayerEntity(p,0,false);party.set(i,p);require(p.isEntityAlive()&&server.getPlayerList().getPlayerByUUID(p.getUniqueID())==p,"Official post-failure death recreation failed");}if(run!=null&&run.getAsJsonObject("members").has(p.getUniqueID().toString())){guide(p,d.exit);server.getCommandManager().executeCommand(p,"narutoarena exit");}}
  if(run!=null){require(ownedRun.equals(ArenaDirector.text(ArenaDirector.run(d),"run")),"Load cleanup ownership changed; preserve replacement run");if(!ArenaDirector.text(run,"state").equals("AVAILABLE"))return;require(run.getAsJsonArray("cells").size()==0,"Owned journal not fully restored");}
  for(EntityPlayerMP p:party)if(server.getPlayerList().getPlayerByUUID(p.getUniqueID())==p){p.inventory.clear();server.getPlayerList().playerLoggedOut(p);}party.clear();row.addProperty("cleanup_public_exit_and_autoreset",true);row.addProperty("cleanup_ticks",cleanupAge);row.addProperty("passed",failures.size()==0&&times.size()==100);cases.add(row);partySize++;if(partySize>4){partySize=1;arenaIndex++;}stage=0;age=0;d=null;run=null;boss=null;row=null;
 }
 private static void finish(){measuring=false;MinecraftForge.EVENT_BUS.unregister(recorder);report.add("standalone_active_budget",timing(allTimes));JsonObject perSize=new JsonObject();for(Map.Entry<Integer,List<Long>> e:bySize.entrySet())perSize.add(e.getKey().toString(),timing(e.getValue()));report.add("standalone_budget_by_party_size",perSize);report.addProperty("measured_cases",cases.size());report.addProperty("total_native_server_tick_samples",allTimes.size());report.addProperty("elapsed_ms",(System.nanoTime()-started)/1000000L);boolean okay=cases.size()==20&&allTimes.size()>=2000;for(JsonElement e:cases)okay&=e.getAsJsonObject().get("passed").getAsBoolean();report.addProperty("passed",okay);done=true;}
 public static boolean tick(){
  if(done)return true;if(arenaIndex>=definitions.size()){finish();return true;}total++;age++;
  try{
   require(total<=7200&&(System.nanoTime()-started)<300000000000L,"Standalone diagnostic reached bounded five-minute/7200tick limit");
   if(stage==0){startCase();return false;}if(stage==80){cleanup();return false;}
   require(alive(),"Genuine participant death/identity loss retained; active window stops");
   if(stage==1){if(age<2)return false;for(EntityPlayerMP p:party)click(p,1);stage=2;age=0;return false;}
   if(stage==2){if(age<2)return false;for(EntityPlayerMP p:party){require(ArenaIntro.complete(p,d),"Real physical native-Ninja introduction did not settle");require((Boolean)Class.forName("net.narutomod.PlayerTracker").getMethod("isNinja",net.minecraft.entity.player.EntityPlayer.class).invoke(null,p),"Actual native Ninja profile unavailable");useStart.put(p.getUniqueID(),p.ticksExisted);p.setActiveHand(EnumHand.MAIN_HAND);}stage=3;age=0;return false;}
   if(stage==3){for(EntityPlayerMP p:party){if(p.ticksExisted-useStart.get(p.getUniqueID())<32||p.isHandActive())return false;require(p.getHeldItemMainhand().isEmpty(),"Enchanted apple was not actually consumed by32native use ticks");useCompleted.putIfAbsent(p.getUniqueID(),p.ticksExisted-useStart.get(p.getUniqueID()));}ArenaDirector.admit(party.get(0),d,true);run=ArenaDirector.run(d);ownedRun=ArenaDirector.text(run,"run");for(int i=1;i<party.size();i++)ArenaDirector.join(party.get(i),d);Entity e=world().getEntityFromUuid(UUID.fromString(ArenaDirector.text(run,"boss_uuid")));require(e instanceof EntityLivingBase,"Exact native admitted boss unavailable");boss=(EntityLivingBase)e;engage();stage=20;age=0;return false;}
   require(run==ArenaDirector.run(d)&&ownedRun.equals(ArenaDirector.text(run,"run"))&&ArenaDirector.text(run,"state").startsWith("PHASE")&&boss.isEntityAlive(),"Actual native encounter changed or terminated");defend();
   if(stage==20){if(!ArenaDirector.courtReady(d,run))return false;int phase=ArenaDirector.sealPhase(run);if(ArenaDirector.pressure(run,phase)<40)return false;if(phase==Math.min(partySize,3)){beginMeasurement();return false;}clickPhase=phase;click(party.get(0),0);stage=21;age=0;return false;}
   if(stage==21){if(age<2)return false;click(party.get(0),1);stage=22;age=0;return false;}
   if(stage==22){if(age<2)return false;require(ArenaDirector.sealPhase(run)==clickPhase+1,"Real physical seals did not advance the charged phase");engage();stage=20;return false;}
   if(stage==50){if(times.size()>=100){endMeasurement();return false;}}
  }catch(Throwable failure){if(row==null){report.addProperty("startup_failure",failure.toString());finish();return true;}failures.add(failure.toString());row.addProperty("failure_stage",stage);row.addProperty("actual_short_window_samples",times.size());int failedStage=stage;if(stage==50&&!measurementRecorded)endMeasurement();measuring=false;if(failedStage==80||total>7200||(System.nanoTime()-started)>=300000000000L){for(EntityPlayerMP p:party)if(server.getPlayerList().getPlayerByUUID(p.getUniqueID())==p){p.inventory.clear();server.getPlayerList().playerLoggedOut(p);}row.addProperty("passed",false);row.addProperty("cleanup_quarantined",true);cases.add(row);party.clear();arenaIndex++;partySize=1;stage=0;run=null;boss=null;row=null;if(total>7200||(System.nanoTime()-started)>=300000000000L){finish();return true;}}else{stage=80;cleanupAge=0;}}
  return false;
 }
 public static final class Recorder {
  private long start;
  @SubscribeEvent(priority=EventPriority.HIGHEST)public void start(TickEvent.ServerTickEvent e){if(measuring&&e.phase==TickEvent.Phase.START)start=System.nanoTime();}
  @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public void attack(LivingAttackEvent e){if(!measuring||!(e.getEntityLiving() instanceof EntityPlayerMP)||!party.contains(e.getEntityLiving())||pending.size()>=200)return;pending.add(new Damage(e,row));}
  @SubscribeEvent(priority=EventPriority.LOWEST)public void end(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END)return;for(Damage p:pending){JsonObject a=new JsonObject();a.addProperty("source",p.e.getSource().damageType);a.addProperty("final_canceled",p.e.isCanceled());Entity source=p.e.getSource().getTrueSource();a.addProperty("native_true_source_class",source==null?"":source.getClass().getName());a.addProperty("health_after_unwind",p.e.getEntityLiving().getHealth());a.addProperty("absorption_after_unwind",p.e.getEntityLiving().getAbsorptionAmount());boolean exact=source==boss;
   if(!exact&&source!=null&&run!=null&&run.has("owned_native_allies")&&run.getAsJsonObject("owned_native_allies").has(source.getUniqueID().toString())){JsonObject ally=run.getAsJsonObject("owned_native_allies").getAsJsonObject(source.getUniqueID().toString());exact=world().getEntityFromUuid(source.getUniqueID())==source&&ownedRun.equals(source.getEntityData().getString("HbvArenaAllyRun"))&&boss.getUniqueID().toString().equals(ArenaDirector.text(ally,"leader_uuid"))&&ArenaTerminals.classHash(source).equals(ArenaDirector.text(ally,"class_sha256"));}
   a.addProperty("exact_run_owned_boss_or_ally_source",exact);p.destination.getAsJsonArray("actual_damage_events").add(a);if(p.e.getSource().damageType.startsWith("hbvArena"))hazardAttacks++;else if(exact)nativeAttacks++;else unattributedAttacks++;}pending.clear();
   if(!measuring||start==0||times.size()>=100)return;long end=System.nanoTime();times.add(end-start);if(firstSample==0)firstSample=start;lastSample=end;start=0;if(boss.ticksExisted>measurementBodyLast)bodyUpdates++;measurementBodyLast=boss.ticksExisted;if(boss instanceof EntityLiving&&party.contains(((EntityLiving)boss).getAttackTarget()))targetTicks++;maxChunks=Math.max(maxChunks,world().getChunkProvider().getLoadedChunks().size());maxEntities=Math.max(maxEntities,world().loadedEntityList.size());int effects=0;for(EntityPlayerMP p:party)effects+=p.getActivePotionEffects().size();maxEffects=Math.max(maxEffects,effects);maxAllies=Math.max(maxAllies,run.has("owned_native_allies")?run.getAsJsonObject("owned_native_allies").size():0);maxJournal=Math.max(maxJournal,run.getAsJsonArray("cells").size());Runtime vm=Runtime.getRuntime();peakHeap=Math.max(peakHeap,vm.totalMemory()-vm.freeMemory());if(times.size()>=100)measuring=false;
  }
 }
}
